create or replace TABLE LDL_DATA_PRODUCTION.CORE_REL.T_REAL_ESTATE (
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	REAL_ESTATE_NR VARCHAR(20) NOT NULL COMMENT 'The number which uniquely identifies a real estate object within a country organization.',
	REAL_ESTATE_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the real estate object.',
	REAL_ESTATE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for real estate objects.',
	OWNERSHIP_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the ownership type of a real estate object, i.e. if it has been bought or if it is rented.',
	OWNERSHIP_RATIO_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the ownership ratio of a real estate object, i.e. if it is fully owned or partly owned.',
	OWN_ACQUISITION_FG BOOLEAN COMMENT 'An indicator showing, if the real estate object was acquired by the Schwarz Group without involvement of a third party.',
	REAL_ESTATE_USG_TYPE_CD VARCHAR(20) COMMENT 'The code for the way, how a real estate object is used. An object may be used by the organization or by a third party.',
	WH_BUILDING_TYPE_CD VARCHAR(20) COMMENT 'The code for the subtype discriminator for warehouse building.',
	WH_PURPOSE_CD VARCHAR(20) COMMENT 'The code identifying the purpose of a warehouse.',
	SHARED_USG_FG BOOLEAN COMMENT 'An indicator showing, if the warehouse is used by multiple parties.',
	CONTRACT_DT DATE COMMENT 'The date when the contract for this real estate object was signed.',
	PRECONTRACT_DT DATE COMMENT 'The date when the precontract / letter of intent for this real estate object was signed.',
	CONSTRUCTION_START_DT DATE COMMENT 'The date when construction started for this real estate object.',
	CONSTRUCTION_END_DT DATE COMMENT 'The date when construction finished for this real estate object.',
	OPEN_DT DATE COMMENT 'The date when this real estate object was opened.',
	PLANNED_OPEN_DT DATE COMMENT 'The date when this real estate object was intended to open.',
	CLOSE_DT DATE COMMENT 'The date when this real estate object was closed.',
	PLANNED_CLOSE_DT DATE COMMENT 'The date when this real estate object was inteded to be closed.',
	PROJECT_CANCEL_DT DATE COMMENT 'The date when the Schwarz Group had no intention to build a real estate object any more, i.e. when the project was cancelled.',
	PROJECT_TERM_DT DATE COMMENT 'The date when the project was terminated, i.e. when the real estate object was closed and there were no legal obligations any more.',
	SALES_AREA_MEAS NUMBER(38,5) COMMENT 'The space which can be used for sales, in the unit indicated by the unit of measure code (e.g. m2).',
	STORAGE_AREA_MEAS NUMBER(38,5) COMMENT 'The space which can be used for storing goods, in the unit indicated by the unit of measure code (e.g. m2).',
	TOTAL_SUBLET_AREA_MEAS NUMBER(38,5) COMMENT 'The total space which can be sublet, in the unit indicated by the unit of measure code (e.g. m2).',
	RENTED_SUBLET_AREA_MEAS NUMBER(38,5) COMMENT 'The space which is currently rented out, in the unit indicated by the unit of measure code.',
	UOM_CD VARCHAR(20) COMMENT 'The code identifying the unit of measure for the sales area.',
	TOTAL_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The total number of parking spaces that are assigned to this building.',
	OWN_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The number of parking spaces that are assigned to this building and which are owned by the Schwarz Group.',
	UNDERGROUND_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The total number of parking spaces in an underground parking garage that are assigned to this building.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_REAL_ESTATE primary key (REAL_ESTATE_SID, DWH_VALID_FROM_TMSP)
)COMMENT='Real Estate is property in the form of land or buildings.'
;